import pytest

from bedrock_protocol import nbt, v1001, v2168

# generated by gophertunnel b8bd735:
# packet.UpdateTrade{WindowID: 1, WindowType: 15, Size: 3, TradeTier: 2, VillagerUniqueID: 42, EntityUniqueID: 7,
# DisplayName: "entity.villager.farmer", NewTradeUI: true, DemandBasedPrices: false,
# SerialisedOffers: nbt.MarshalEncoding(map[string]any{"TierExpRequirements": int32(5)}, nbt.NetworkLittleEndian)}
FARMER = bytes.fromhex(
    "010f0604540e16656e746974792e76696c6c616765722e6661726d657201000a00031354696572457870526571756972656d656e74730a00"
)

# generated by gophertunnel b8bd735:
# packet.UpdateTrade{WindowID: 0xff, WindowType: 0xf7, Size: -1, TradeTier: -1, VillagerUniqueID: -1,
# EntityUniqueID: -1, DisplayName: "", NewTradeUI: false, DemandBasedPrices: true,
# SerialisedOffers: nbt.MarshalEncoding(map[string]any{}, nbt.NetworkLittleEndian)}
NONE = bytes.fromhex("fff7010101010000010a0000")

# generated by gophertunnel b8bd735:
# packet.UpdateTrade{WindowID: 1, WindowType: 15, Size: 300, TradeTier: 0, VillagerUniqueID: 0, EntityUniqueID: 0,
# DisplayName: "", NewTradeUI: false, DemandBasedPrices: false,
# SerialisedOffers: nbt.MarshalEncoding(map[string]any{}, nbt.NetworkLittleEndian)}
WIDE = bytes.fromhex("010fd8040000000000000a0000")

GOLDENS = [
    pytest.param(
        v2168.UpdateTradePacket(
            container_id=v2168.ContainerID.FIRST,
            type=v2168.ContainerType.TRADE,
            size=3,
            trader_tier=2,
            entity_unique_id=42,
            last_trading_player=7,
            display_name="entity.villager.farmer",
            use_new_trade_screen=True,
            using_economy_trade=False,
            data=nbt.CompoundTag({"TierExpRequirements": nbt.IntTag(5)}),
        ),
        FARMER,
        id="farmer",
    ),
    pytest.param(
        v2168.UpdateTradePacket(
            container_id=v2168.ContainerID.NONE,
            type=v2168.ContainerType.NONE,
            size=-1,
            trader_tier=-1,
            entity_unique_id=-1,
            last_trading_player=-1,
            display_name="",
            use_new_trade_screen=False,
            using_economy_trade=True,
        ),
        NONE,
        id="sentinels",
    ),
    pytest.param(
        v2168.UpdateTradePacket(
            container_id=v2168.ContainerID.FIRST,
            type=v2168.ContainerType.TRADE,
            size=300,
        ),
        WIDE,
        id="wide-size",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_update_trade_is_packet_80(version):
    assert version.packets[80] is version.UpdateTradePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_trade_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_trade_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
